import express from 'express';
import { Database } from 'bun:sqlite';
import { requireCorporateUser } from '../auth/corporate.js';

const app = express();
const db = new Database('./storage/legal_records.sqlite');

app.get('/api/legal/agreements/:agreementId/status', requireCorporateUser, (req, res) => {
  const { agreementId } = req.params;

  // Validate that the agreement is associated with the user's verified corporate account
  const query = db.query(`
    SELECT id, document_title, signer_email, status, signed_at, company_name
    FROM legal_agreements
    WHERE id = ? AND company_id = ?
  `);

  const agreement = query.get(agreementId, req.user.companyId);
  if (!agreement) {
    return res.status(404).json({ error: 'Agreement not found or access denied' });
  }

  res.json({ agreement });
});

export default app;
